userscript.function:

doServiceAjax("sepoa.svc.admin.AD_421", "CONNECTION", "doQueryMenuFilter", {HOUSE_CODE: Sepoa.info.HOUSE_CODE, "CODE":Sepoa.info.MENU_PROFILE_CODE}, function(so){
    var sf = new SepoaFormater(so.result[0]);
    var menuItems = {}
    var menuItemsList = [];
    for(var i=0;i<sf.getRowCount();i++) {
        var menuData = {};
        for(var j=0;j<sf.columns.length;j++){
            var columnName = sf.columns;
            menuData[columnName[j]]= sf.getValue(columnName[j],i);
        }
        menuData.childs = [];
        menuItems[menuData.MENU_ID] = menuData;
        menuItemsList.push(menuData);
    }

    var menuTree = [];
    for(var i in menuItemsList){
        var item = menuItemsList[i];
        var parent = item.PARENT_MENU_ID;
        if(parent == "0"){
            menuTree.push(item);
        }else{
            menuItems[item.PARENT_MENU_ID].childs.push(item);
        }
    }

    doRenderMenu(menuTree);
    doRenderSummary();
})


for(var i in menuTree){
    var groupData = menuTree[i];
    var childNodes = groupData.childs;

    if(menuTree[i].HIDDEN_FLAG == "Y" || menuTree[i].MENU_FILTERED_YN == "N"){
        continue;
    }
    if(childNodes.length <= 0){
        continue;
    }

    const tileRenderer = new SepoaMenuTileRenderer();
    tileRenderer.attachEvent("onItemClick", (option)=>{
        linkTo(option);
    })

    for(let j in childNodes){
        const node = childNodes[j];
        if(node.HIDDEN_FLAG != "Y" && node.MENU_FILTERED_YN != "N"){
            tileRenderer.addItem({
                id:node.SCREEN_ID,
                seq:node.ITEM_SEQ,
                label:Sepoa.cache.text.get("MENU_"+node.MENU_PROFILE_CODE+"."+node.MENU_ID),
                url:node.URL,
                mobileUrl:node.MOBILE_URL,
                img:node.MENU_IMG,
                summary:node.SUMMARY_FLAG
            });
        }
    }

    if(tileRenderer.getItemCount() > 0){
        const div = menuContainer.appendChild(document.createElement("div"));
        div.classList.add("groupbox");
        tileRenderer.draw({
            base:div,
            label:Sepoa.cache.text.get("MENU_"+groupData.MENU_PROFILE_CODE+"."+groupData.MENU_ID)
        });
    }
}


$("div[class*=component__summary]").each(function (idx){
    var url= window.CONTEXT_NAME+'/SepoaAjax.sux';
    dataOutput.setValue('SCREEN_ID',this.lang);
    var params = "?nickName=sepoa.svc.summary.Summary&conType=CONNECTION&methodName=getSummaryCount&_encode=true" + dataOutput.getParams();
    url = url + params;
    var that = this;
    $.ajax({
        type:"POST",
        url:url,
        data:params,
        dataType:"xml",
        success:function(xmlDoc){
            var sepoaOut = Object();
            var status_nodes  = xmlDoc.getElementsByTagName("status");
            var message_nodes = xmlDoc.getElementsByTagName("message");
            var result_nodes  = xmlDoc.getElementsByTagName("result");
            var status  = "";
            if(status_nodes[0].firstChild != null) {
                status  = status_nodes[0].firstChild.nodeValue;
            }
            var message = "";
            if( message_nodes[0].firstChild != null ) {
                message = message_nodes[0].firstChild.nodeValue;
            }

            var result  = new Array();
            var result_size = result_nodes.length;
            for(var i = 0; i < result_size; i++) {
                if( result_nodes[i].firstChild != null ) {
                    result.push(result_nodes[i].firstChild.nodeValue);
                }
            }
            sepoaOut.status = status;
            sepoaOut.message = message;
            sepoaOut.result = result;

            if(sepoaOut.status == "0"){
                //console.log(that.lang + " Summary 데이타 조회 실패.");
                that.innerHTML = "X";
            }else if(sepoaOut.status == "SESSIONCLOSE"){
                sUtils.system.login();
            } else{
                that.innerHTML = sepoaOut.result[0];
            }
        },
        error:function(e){
            //console.log(that.lang + " AJAX 통신 실패.");
        }
    });
});
